ALTER TABLE public.wk_movement_catalog ADD COLUMN IF NOT EXISTS equipment_alternatives jsonb NOT NULL DEFAULT '[]'::jsonb; COMMENT ON COLUMN public.wk_movement_catalog.equipment_alternatives IS 'Alternative complete gear groups; require all equipment_requirements plus every item in at least one group when nonempty. Never interpret alternatives as requiring all groups.'; ALTER TABLE public.wk_movement_catalog ADD CONSTRAINT wk_catalog_equipment_alternatives_array CHECK (jsonb_typeof(equipment_alternatives) = 'array');